#include <furi.h>
#include <furi_hal_subghz.h>
#include <furi_hal_vibro.h>
#include <gui/gui.h>
#include <input/input.h>
#include <lib/subghz/devices/cc1101_configs.h>

/* generated by fbt from .png files in images folder */
#include <bleepsentry_icons.h>

#define TAG "Bleepsentry"

#define RSSI_POLL_PERIOD_MS 100
#define BASELINE_SAMPLE_MS  2000
#define ALERT_MARGIN_DB     12.0f
#define RSSI_MIN_DBM        -100.0f
#define RSSI_MAX_DBM        0.0f

typedef enum {
    BsEventTypeTick,
    BsEventTypeInput,
} BsEventType;

typedef struct {
    BsEventType type;
    InputEvent input;
} BsEvent;

typedef enum {
    BsModeIdle,
    BsModeScanning,
    BsModeCalibrating,
} BsMode;

static const uint32_t frequencies[] = {
    300000000,
    433920000,
    868350000,
    915000000,
};
#define FREQ_COUNT (sizeof(frequencies) / sizeof(frequencies[0]))

typedef struct {
    FuriMutex* mutex;
    FuriMessageQueue* queue;
    FuriTimer* timer;

    size_t freq_index;
    float rssi;
    float baseline;
    float threshold;
    bool has_baseline;
    bool alerting;
    BsMode mode;

    uint32_t calib_ticks_left;
    float calib_sum;
    uint32_t calib_count;
} BsApp;

static void bs_radio_start(BsApp* app) {
    furi_hal_subghz_reset();
    furi_hal_subghz_idle();
    furi_hal_subghz_load_custom_preset(subghz_device_cc1101_preset_ook_650khz_async_regs);
    furi_hal_subghz_set_frequency_and_path(frequencies[app->freq_index]);
    furi_hal_subghz_flush_rx();
    furi_hal_subghz_rx();
}

static void bs_radio_stop(void) {
    furi_hal_subghz_idle();
    furi_hal_subghz_sleep();
}

static void bs_timer_callback(void* context) {
    BsApp* app = context;
    BsEvent event = {.type = BsEventTypeTick};
    furi_message_queue_put(app->queue, &event, 0);
}

static void bs_input_callback(InputEvent* input_event, void* context) {
    BsApp* app = context;
    BsEvent event = {.type = BsEventTypeInput, .input = *input_event};
    furi_message_queue_put(app->queue, &event, 0);
}

static void bs_draw_callback(Canvas* canvas, void* context) {
    BsApp* app = context;
    furi_mutex_acquire(app->mutex, FuriWaitForever);

    canvas_clear(canvas);
    canvas_set_font(canvas, FontPrimary);
    canvas_draw_str(canvas, 2, 10, "Bleepsentry");

    canvas_set_font(canvas, FontSecondary);
    char buf[48];
    snprintf(
        buf,
        sizeof(buf),
        "%lu.%02lu MHz",
        frequencies[app->freq_index] / 1000000,
        (frequencies[app->freq_index] / 10000) % 100);
    canvas_draw_str(canvas, 2, 22, buf);

    snprintf(buf, sizeof(buf), "RSSI: %d dBm", (int)app->rssi);
    canvas_draw_str(canvas, 2, 33, buf);

    if(app->has_baseline) {
        snprintf(
            buf, sizeof(buf), "Base: %d  Thr: %d", (int)app->baseline, (int)app->threshold);
        canvas_draw_str(canvas, 2, 43, buf);
    } else {
        canvas_draw_str(canvas, 2, 43, "No baseline (press OK)");
    }

    /* RSSI bar */
    int32_t bar_x = 2, bar_y = 48, bar_w = 120, bar_h = 8;
    canvas_draw_frame(canvas, bar_x, bar_y, bar_w, bar_h);
    float frac = (app->rssi - RSSI_MIN_DBM) / (RSSI_MAX_DBM - RSSI_MIN_DBM);
    if(frac < 0) frac = 0;
    if(frac > 1) frac = 1;
    int32_t fill_w = (int32_t)(frac * (bar_w - 2));
    if(fill_w > 0) canvas_draw_box(canvas, bar_x + 1, bar_y + 1, fill_w, bar_h - 2);

    if(app->mode == BsModeCalibrating) {
        canvas_draw_str(canvas, 2, 63, "Calibrating baseline...");
    } else if(app->alerting) {
        canvas_set_font(canvas, FontPrimary);
        canvas_draw_str(canvas, 70, 63, "ALERT");
    }

    furi_mutex_release(app->mutex);
}

static void bs_start_calibration(BsApp* app) {
    app->mode = BsModeCalibrating;
    app->calib_ticks_left = BASELINE_SAMPLE_MS / RSSI_POLL_PERIOD_MS;
    app->calib_sum = 0;
    app->calib_count = 0;
}

int32_t bleepsentry_app(void* p) {
    UNUSED(p);

    BsApp* app = malloc(sizeof(BsApp));
    app->mutex = furi_mutex_alloc(FuriMutexTypeNormal);
    app->queue = furi_message_queue_alloc(8, sizeof(BsEvent));
    app->freq_index = 1; /* 433.92 MHz default */
    app->rssi = RSSI_MIN_DBM;
    app->baseline = RSSI_MIN_DBM;
    app->threshold = RSSI_MIN_DBM;
    app->has_baseline = false;
    app->alerting = false;
    app->mode = BsModeIdle;

    ViewPort* view_port = view_port_alloc();
    view_port_draw_callback_set(view_port, bs_draw_callback, app);
    view_port_input_callback_set(view_port, bs_input_callback, app);

    Gui* gui = furi_record_open(RECORD_GUI);
    gui_add_view_port(gui, view_port, GuiLayerFullscreen);

    bs_radio_start(app);
    app->mode = BsModeScanning;

    app->timer = furi_timer_alloc(bs_timer_callback, FuriTimerTypePeriodic, app);
    furi_timer_start(app->timer, furi_ms_to_ticks(RSSI_POLL_PERIOD_MS));

    bool running = true;
    BsEvent event;
    while(running) {
        if(furi_message_queue_get(app->queue, &event, FuriWaitForever) == FuriStatusOk) {
            furi_mutex_acquire(app->mutex, FuriWaitForever);

            if(event.type == BsEventTypeTick) {
                float rssi = furi_hal_subghz_get_rssi();
                app->rssi = rssi;

                if(app->mode == BsModeCalibrating) {
                    app->calib_sum += rssi;
                    app->calib_count++;
                    if(app->calib_ticks_left > 0) app->calib_ticks_left--;
                    if(app->calib_ticks_left == 0) {
                        app->baseline = app->calib_count ? (app->calib_sum / app->calib_count) :
                                                            RSSI_MIN_DBM;
                        app->threshold = app->baseline + ALERT_MARGIN_DB;
                        app->has_baseline = true;
                        app->mode = BsModeScanning;
                    }
                } else if(app->mode == BsModeScanning && app->has_baseline) {
                    bool was_alerting = app->alerting;
                    app->alerting = rssi > app->threshold;
                    if(app->alerting && !was_alerting) {
                        furi_hal_vibro_on(true);
                        furi_delay_ms(50);
                        furi_hal_vibro_on(false);
                    }
                }
            } else if(event.type == BsEventTypeInput) {
                InputEvent* input = &event.input;
                if(input->type == InputTypeShort || input->type == InputTypeRepeat) {
                    if(input->key == InputKeyBack) {
                        running = false;
                    } else if(input->key == InputKeyOk) {
                        bs_start_calibration(app);
                    } else if(input->key == InputKeyUp || input->key == InputKeyRight) {
                        app->freq_index = (app->freq_index + 1) % FREQ_COUNT;
                        app->has_baseline = false;
                        app->alerting = false;
                        bs_radio_start(app);
                    } else if(input->key == InputKeyDown || input->key == InputKeyLeft) {
                        app->freq_index =
                            (app->freq_index + FREQ_COUNT - 1) % FREQ_COUNT;
                        app->has_baseline = false;
                        app->alerting = false;
                        bs_radio_start(app);
                    }
                }
            }

            furi_mutex_release(app->mutex);
            view_port_update(view_port);
        }
    }

    furi_timer_stop(app->timer);
    furi_timer_free(app->timer);

    bs_radio_stop();

    gui_remove_view_port(gui, view_port);
    furi_record_close(RECORD_GUI);
    view_port_free(view_port);

    furi_message_queue_free(app->queue);
    furi_mutex_free(app->mutex);
    free(app);

    return 0;
}
